using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A bubble sort whose swap loses one of its two values - a = b and then b = a - in each language, with the change that swaps
/// them the language's own way, or gives the second line the value the line above kept; and the same sorts swapping rightly,
/// which are left alone. Each row is what the check gave for the program when these were written.
/// </summary>
public class SwapTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes.</summary>
