    public void ARightSwapIsLeftAlone(string fileName, string code)
    {
        Assert.DoesNotContain(LogicPatterns.Scan(Program(fileName, code)), finding => finding.PatternId.EndsWith("swap-loses-value", StringComparison.Ordinal));
    }
